// Pre-flight: refuses unless the order is on ordermergetest2, test:true, with only bogus test:true money transactions,
// and not one of the pre-existing Protocol v2 fixture orders (those use gateway "manual").
import { spawnSync } from 'child_process';
import fs from 'fs';
const [orderId] = process.argv.slice(2);
const D = process.env.D;
fs.writeFileSync(D + '/guard.graphql', `query G($id: ID!) { shop { myshopifyDomain plan { partnerDevelopment } } order(id: $id) { id name test sourceName paymentGatewayNames transactions(first: 20) { kind status gateway test } } }`);
fs.writeFileSync(D + '/guard.vars.json', JSON.stringify({ id: orderId }));
const r = spawnSync('npx', ['shopify','store','execute','--store','ordermergetest2.myshopify.com','--version','2026-04','--query-file',D+'/guard.graphql','--variable-file',D+'/guard.vars.json'], { cwd: '<home>/Desktop/shopifymerger/order-merge-app', encoding: 'utf8', shell: true });
const t = ((r.stdout||'')+(r.stderr||'')).replace(/\x1b\[[0-9;]*[A-Za-z]/g,'');
const j = JSON.parse(t.slice(t.indexOf('{\n'), t.lastIndexOf('}')+1));
const fail = (m) => { console.error('GUARD FAIL: ' + m); process.exit(4); };
if (j.shop.myshopifyDomain !== 'ordermergetest2.myshopify.com') fail('wrong shop');
if (!j.shop.plan.partnerDevelopment) fail('not a development store');
const o = j.order; if (!o) fail('order not found');
if (o.test !== true) fail('order.test is not true');
if (!o.paymentGatewayNames.length || o.paymentGatewayNames.some(g => g !== 'bogus')) fail('non-bogus gateway: ' + o.paymentGatewayNames);
if (o.transactions.some(x => x.test !== true)) fail('a transaction is not test:true');
console.log('GUARD OK', o.name, o.id, 'gateway=bogus test=true shop=ordermergetest2 partnerDevelopment=true');

