mutation E6Refund($input: RefundInput!) {
  refundCreate(input: $input) @idempotent(key: "572abfe8-ecb3-4a41-8847-c7f3f0e3eb25") {
    refund {
      id note createdAt processedAt
      totalRefundedSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
      refundShippingLines(first: 5) { nodes { id subtotalAmountSet { shopMoney { amount } } taxAmountSet { shopMoney { amount } } shippingLine { id title } } }
      transactions(first: 5) { nodes { id kind status gateway test processedAt errorCode amountSet { shopMoney { amount currencyCode } } parentTransaction { id kind } } }
    }
    order { id displayFinancialStatus totalRefundedShippingSet { shopMoney { amount } } totalRefundedSet { shopMoney { amount } } }
    userErrors { field message }
  }
}

fragment SR on SuggestedRefund {
  amountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
  subtotalSet { shopMoney { amount } }
  totalTaxSet { shopMoney { amount } }
  maximumRefundableSet { shopMoney { amount currencyCode } }
  shipping {
    amountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
    taxSet { shopMoney { amount } }
    maximumRefundableSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
  }
  refundLineItems { quantity lineItem { id } }
  suggestedTransactions {
    kind gateway formattedGateway
    amountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
    maximumRefundableSet { shopMoney { amount currencyCode } }
    parentTransaction { id kind status test gateway }
  }
  suggestedRefundMethods { __typename amount { shopMoney { amount } } maximumRefundable { shopMoney { amount } } }
}
query Probe($id: ID!, $amt: Money) {
  order(id: $id) {
    name cancelledAt closedAt closed refundable taxesIncluded displayFinancialStatus
    totalRefundedShippingSet { shopMoney { amount } }
    netPaymentSet { shopMoney { amount } }
    transactions(first: 10) { id kind status gateway test amountSet { shopMoney { amount currencyCode } } maximumRefundableV2 { amount currencyCode } parentTransaction { id } }
    byAmount: suggestedRefund(shippingAmount: $amt) { ...SR }
    byFlag: suggestedRefund(refundShipping: true) { ...SR }
    zero: suggestedRefund(shippingAmount: "0.00") { ...SR }
  }
}

